// Package service registers the host as a boot service (`service install`,
// running `serve --supervise` as the installing user), registers the tray to
// start at login (`autostart`), and runs the supervisor of `serve --supervise`.
//
// The files and scripts each platform registers are generated by the pure
// functions in files.go, which are tested on every OS; only running them is
// build-tagged per platform.
package service

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"time"

	"github.com/n2ns/n2n-nexus/host/internal/config"
	"github.com/n2ns/n2n-nexus/host/internal/host"
)

// ErrNotElevated is returned when the command needs administrator / root rights.
var ErrNotElevated = errors.New("needs administrator rights")

// Options are the flags of `service install|uninstall|status`.
type Options struct {
	Exe  string
	Root string // --root, "" for the default data directory
	Host string // --host, "" to keep settings.json
	Port int    // --port, -1 to keep settings.json
	Out  io.Writer
}

// target is who and where the service runs.
type target struct {
	exe, dataDir, logDir string
	user, home           string
	uid, gid             int // -1 when ownership need not change
}

// resolve fills in the data directory and the user the service runs as.
func resolve(o Options) (target, error) {
	t, err := currentTarget(o.Exe)
	if err != nil {
		return t, err
	}
	if o.Root != "" {
		abs, err := filepath.Abs(o.Root)
		if err != nil {
			return t, err
		}
		t.dataDir = abs
	}
	return t, nil
}

// settingsFor loads settings.json and applies the flags.
func settingsFor(t target, o Options) (config.Settings, error) {
	s, err := config.LoadSettings(t.dataDir)
	if err != nil {
		return s, err
	}
	s.Override(o.Host, o.Port)
	if s.Port == 0 {
		return s, errors.New("a service needs a fixed port: --port 1-65535")
	}
	return s, s.Validate()
}

// HealthAddr is the address to probe a host bound to bindHost on: the
// loopback of the wildcard's family, since each wildcard binds its family only.
func HealthAddr(bindHost string, port int) string {
	switch bindHost {
	case "0.0.0.0", "":
		bindHost = "127.0.0.1"
	case "::":
		bindHost = "::1"
	}
	return net.JoinHostPort(bindHost, strconv.Itoa(port))
}

// HealthInfo is what GET /health reports about a host.
type HealthInfo struct {
	Version string
	Online  int // agent sessions that are not offline
}

// Health asks http://addr/health whether an n2n-nexus host answers and what it reports.
func Health(addr string, timeout time.Duration) (HealthInfo, bool) {
	c := http.Client{Timeout: timeout}
	resp, err := c.Get("http://" + addr + "/health")
	if err != nil {
		return HealthInfo{}, false
	}
	defer resp.Body.Close()
	var body struct {
		Service  string `json:"service"`
		Version  string `json:"version"`
		Sessions struct {
			Online int `json:"online"`
		} `json:"sessions"`
	}
	if json.NewDecoder(io.LimitReader(resp.Body, 1<<16)).Decode(&body) != nil || body.Service != "n2n-nexus" {
		return HealthInfo{}, false
	}
	return HealthInfo{Version: body.Version, Online: body.Sessions.Online}, true
}

// Probe asks http://addr/health whether an n2n-nexus host answers and returns its version.
func Probe(addr string, timeout time.Duration) (version string, ok bool) {
	h, ok := Health(addr, timeout)
	return h.Version, ok
}

// refuseTray fails when a tray runs the host for dataDir in-process: the
// tray is the lock holder itself, so stopping it would end the whole tray.
func refuseTray(dataDir string) error {
	info, err := host.ReadLock(dataDir)
	if err != nil || !info.Held || info.Role != host.RoleTray {
		return err
	}
	return fmt.Errorf("the n2n-nexus-host tray (PID %d) runs the host for %s: quit the n2n-nexus-host tray first; after the service starts, the tray can be opened again and will control it", info.PID, dataDir)
}

// StopLockHolder stops the host holding dataDir's lock, by the PIDs it
// recorded there (its supervisor first, so it is not restarted), and waits
// until the lock is free. It never stops a tray (see refuseTray).
func StopLockHolder(dataDir string, out io.Writer) error {
	if err := refuseTray(dataDir); err != nil {
		return err
	}
	info, err := host.ReadLock(dataDir)
	if err != nil || !info.Held {
		return err
	}
	for _, pid := range []int{info.Supervisor, info.PID} {
		if pid <= 0 {
			continue
		}
		if err := StopPID(pid); err != nil {
			fmt.Fprintf(out, "Could not stop PID %d: %v\n", pid, err)
		} else {
			fmt.Fprintf(out, "Stopped n2n-nexus-host PID %d.\n", pid)
		}
	}
	for i := 0; i < 100; i++ {
		if info, err := host.ReadLock(dataDir); err == nil && !info.Held {
			return nil
		}
		if i == 50 && info.PID > 0 {
			_ = KillPID(info.PID)
		}
		time.Sleep(100 * time.Millisecond)
	}
	return fmt.Errorf("PID %d still holds %s", info.PID, host.LockFile(dataDir))
}

// describeRunning prints which host runs for dataDir and what answers on the port.
func describeRunning(out io.Writer, t target, s config.Settings) (ours bool) {
	info, _ := host.ReadLock(t.dataDir)
	addr := HealthAddr(s.Host, s.Port)
	version, answering := Probe(addr, time.Second)
	switch {
	case info.Held && answering:
		fmt.Fprintf(out, "n2n-nexus-host %s is running for %s (PID %d) on http://%s.\n", version, t.dataDir, info.PID, addr)
		return true
	case info.Held:
		fmt.Fprintf(out, "n2n-nexus-host is running for %s (PID %d), but nothing answers on http://%s.\n", t.dataDir, info.PID, addr)
	case answering:
		fmt.Fprintf(out, "An n2n-nexus host %s answers on http://%s, but not for %s.\n", version, addr, t.dataDir)
	default:
		fmt.Fprintf(out, "No n2n-nexus-host is running for %s.\n", t.dataDir)
	}
	if owner := portOwner(s.Port); owner != "" {
		fmt.Fprintf(out, "Port %d is used by %s\n", s.Port, owner)
	}
	return false
}

// Install refuses while a tray runs the host for the data directory; else it
// stops a host running for it, writes the flags to settings.json, registers
// and starts the service, and reports who listens.
func Install(o Options) error {
	t, err := resolve(o)
	if err != nil {
		return err
	}
	if err := requireAdmin(); err != nil {
		return err
	}
	if err := checkTarget(t); err != nil {
		return err
	}
	s, err := settingsFor(t, o)
	if err != nil {
		return err
	}
	if err := refuseTray(t.dataDir); err != nil {
		return err
	}
	if info, _ := host.ReadLock(t.dataDir); info.Held {
		fmt.Fprintf(o.Out, "Stopping the n2n-nexus-host running for %s (PID %d).\n", t.dataDir, info.PID)
	}
	if err := stopService(t, o.Out); err != nil {
		return err
	}
	if err := StopLockHolder(t.dataDir, o.Out); err != nil {
		return err
	}
	if err := mkdirOwned(t, t.dataDir); err != nil {
		return err
	}
	if err := mkdirOwned(t, t.logDir); err != nil {
		return err
	}
	if err := config.SaveSettings(t.dataDir, s); err != nil {
		return err
	}
	if err := chownTo(t, config.SettingsFile(t.dataDir)); err != nil {
		return err
	}
	fmt.Fprintf(o.Out, "Settings: %s (host %s, port %d).\n", config.SettingsFile(t.dataDir), s.Host, s.Port)
	if err := register(t, o.Out); err != nil {
		return err
	}
	for i := 0; i < 50; i++ {
		info, _ := host.ReadLock(t.dataDir)
		if _, ok := Probe(HealthAddr(s.Host, s.Port), 500*time.Millisecond); ok && info.Held {
			break
		}
		time.Sleep(200 * time.Millisecond)
	}
	if !describeRunning(o.Out, t, s) {
		fmt.Fprintf(o.Out, "See %s.\n", host.LogFile(t.logDir))
	}
	if s.Host != "127.0.0.1" && s.Host != "localhost" {
		fmt.Fprintf(o.Out, "Other machines reach it only if the firewall allows TCP %d and UDP %d (discovery) from them.\n", s.Port, s.DiscoveryPort)
	}
	return nil
}

// Uninstall removes the service and stops the service's host still running for the data directory.
func Uninstall(o Options) error {
	t, err := resolve(o)
	if err != nil {
		return err
	}
	if err := requireAdmin(); err != nil {
		return err
	}
	if err := unregister(t, o.Out); err != nil {
		return err
	}
	return stopServiceHost(t.dataDir, o.Out)
}

// stopServiceHost stops the host holding dataDir's lock only when it is the
// service's (a supervised serve); a tray or a foreground serve keeps running.
func stopServiceHost(dataDir string, out io.Writer) error {
	info, err := host.ReadLock(dataDir)
	if err != nil || !info.Held {
		return err
	}
	if info.Role != host.RoleSupervised {
		fmt.Fprintf(out, "n2n-nexus-host PID %d (%s) keeps running for %s: it is not the service.\n", info.PID, info.Role, dataDir)
		return nil
	}
	return StopLockHolder(dataDir, out)
}

// Status prints whether the service is installed and running, and who listens on the port.
func Status(o Options) error {
	t, err := resolve(o)
	if err != nil {
		return err
	}
	s, err := config.LoadSettings(t.dataDir)
	if err != nil {
		return err
	}
	s.Override(o.Host, o.Port)
	fmt.Fprintf(o.Out, "Service: %s\n", serviceState(t))
	describeRunning(o.Out, t, s)
	return nil
}

// Executable is the path of the running program.
func Executable() (string, error) {
	exe, err := os.Executable()
	if err != nil {
		return "", err
	}
	return filepath.Abs(exe)
}
